export function TecfysLogo({
  size = 32,
  discColor = TECFYS_DISC,
  className,
  title = "Tecfys",
}: {
  size?: number;
  discColor?: string;
  className?: string;
  /** Accessible name; pass null when the logo sits next to the visible "Tecfys" text. */
  title?: string | null;
}) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 100 100"
      width={size}
      height={size}
      className={cn("shrink-0 text-[#FCF9F3]", className)}
      role={title ? "img" : undefined}
      aria-label={title ?? undefined}
      aria-hidden={title ? undefined : true}
      focusable="false"
    >
      <circle cx="50" cy="50" r="50" fill={discColor} />
      <path fill="currentColor" fillRule="evenodd" d={TECFYS_GLYPH_PATH} />
    </svg>
  );
}
